    if value.startswith("/") or any(part in ("", ".", "..") for part in parts):
        raise ValueError("unsafe path")


def _text(value, field):
    if type(value) is not str:
        raise ValueError(f"{field} must be a string")
    return value


def _contract(payloads, contract):
    _validate(payloads)
    _validate(contract)
    if type(payloads) is not list or type(contract) is not dict:
        raise ValueError("invalid transform arguments")
    for field in ("name", "operation", "inputs", "output"):
        if field not in contract:
            raise ValueError(f"contract is missing {field}")
    _safe_path(contract["output"])
    if type(contract["inputs"]) is not list:
        raise ValueError("invalid contract inputs")
    for item in contract["inputs"]:
        if type(item) is not str:
            raise ValueError("invalid contract inputs")
        _safe_path(item)
    inputs = contract.get("inputs")
    if contract.get("name") != "mount" or contract.get("operation") != "mount_parse":
        raise ValueError("invalid component contract")
    if type(inputs) is not list or len(payloads) != len(inputs) or len(payloads) != 1:
        raise ValueError("mount requires one input")
    payload = payloads[0]
    if type(payload) is dict and set(payload) == {"name", "result"}:
        payload = payload["result"]
    if type(payload) is not dict or "mount" not in payload:
        raise ValueError("mount input is missing")
    return _text(payload["mount"], "mount")


PATTERN = re.compile(r"(\S+) on (\S+) type (\S+) \((.+)\)")


def _options(value):
    return sorted(set(value.split(",")))


def transform(payloads, contract):
    records = []
    for raw_line in _contract(payloads, contract).splitlines():
        line = raw_line.strip()
        if not line:
            continue
        match = PATTERN.fullmatch(line)
        if match is None:
            raise ValueError("invalid mount line")
        device, mount, fstype, options = match.groups()
        records.append({
            "device": device.replace("\\040", " "),
            "mount": mount.replace("\\040", " "),
            "fstype": fstype,
            "options": _options(options),
        })
    return {"name": "mount", "result": {"records": records}}
