def _string(value, field):
    if type(value) is not str or not value.strip():
        raise ValueError(f"{field} must be a non-empty string")
    return value


def _records(payload, source):
    if type(payload) is not dict or type(payload.get("records")) is not list:
        raise ValueError(f"invalid {source} records")
    records = []
    for item in payload["records"]:
        if type(item) is not dict:
            raise ValueError(f"invalid {source} record")
        for field in ("device", "mount", "fstype"):
            if field not in item:
                raise ValueError(f"{source} record is missing {field}")
            _string(item[field], f"{source}.{field}")
        options = item.get("options")
        if type(options) is not list or any(type(option) is not str or not option.strip() for option in options):
            raise ValueError(f"invalid {source}.options")
        records.append({
            "device": item["device"],
            "mount": item["mount"],
            "fstype": item["fstype"],
            "options": list(options),
        })
    return records


def transform(payloads, contract):
    _validate(payloads)
    _validate(contract)
    if type(payloads) is not list or type(contract) is not dict:
        raise ValueError("invalid transform arguments")
    for field in ("name", "operation", "inputs", "output"):
        if field not in contract:
            raise ValueError(f"contract is missing {field}")
    _safe_path(contract["output"])
    if type(contract["inputs"]) is not list:
        raise ValueError("invalid contract inputs")
    for item in contract["inputs"]:
        if type(item) is not str:
            raise ValueError("invalid contract inputs")
        _safe_path(item)
    if contract.get("name") != "merged" or contract.get("operation") != "mount_merge":
        raise ValueError("invalid component contract")
    inputs = contract.get("inputs")
    if type(inputs) is not list or len(payloads) != len(inputs) or len(payloads) != 3:
        raise ValueError("mount merge requires three inputs")
    sources = ("fstab", "aix", "mount")
    grouped = {}
    for source, payload in zip(sources, payloads):
        if type(payload) is dict and set(payload) == {"name", "result"}:
            payload = payload["result"]
        if type(payload) is not dict:
            raise ValueError(f"invalid {source} records")
        for record in _records(payload, source):
            grouped.setdefault(record["mount"], []).append((source, record))
    records = []
    conflicts = []
    for mount in sorted(grouped):
        evidence = grouped[mount]
        winner = dict(evidence[0][1])
        winner["source"] = evidence[0][0]
        records.append(winner)
        distinct = {(item["device"], item["fstype"], tuple(item["options"])) for _, item in evidence}
        if len(distinct) > 1:
            conflict_evidence = []
            for source, item in evidence:
                enriched = dict(item)
                enriched["source"] = source
                conflict_evidence.append(enriched)
            conflicts.append({"mount": mount, "evidence": conflict_evidence})
    return {"name": "merged", "result": {"records": records, "conflicts": conflicts}}
