import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def main():
    contracts = sorted(path for path in ROOT.rglob("contract.json") if "outputs" not in path.relative_to(ROOT).parts)
    if not contracts:
        raise ValueError("no component contracts")
    pending = {path: {ROOT / item for item in _inputs(path)} for path in contracts}
    outputs = {ROOT / _output(path) for path in contracts}
    if len(outputs) != len(contracts):
        raise ValueError("duplicate component output")
    completed = {dependency for dependencies in pending.values() for dependency in dependencies
                 if dependency not in outputs and dependency.is_file()}
    missing = {dependency for dependencies in pending.values() for dependency in dependencies
               if dependency not in outputs and not dependency.is_file()}
    if missing:
        raise ValueError(f"missing dependencies: {', '.join(sorted(str(path) for path in missing))}")
    while pending:
        ready = [path for path, dependencies in pending.items() if dependencies <= completed]
        if not ready:
            raise ValueError("component dependency cycle")
        for path in ready:
            subprocess.run([sys.executable, str(path.with_name("render.py"))], cwd=ROOT, check=True)
            completed.add(ROOT / _output(path))
            del pending[path]
    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


def _inputs(path):
    import json
    contract = json.loads(path.read_text(encoding="utf-8"))
    if type(contract) is not dict or type(contract.get("inputs")) is not list:
        raise ValueError("invalid contract")
    return contract["inputs"]


def _output(path):
    import json
    contract = json.loads(path.read_text(encoding="utf-8"))
    if type(contract) is not dict or type(contract.get("output")) is not str:
        raise ValueError("invalid contract")
    return contract["output"]


if __name__ == "__main__":
    main()
