def _attention(result):
    if result.get("blocked") is True:
        return True
    for field in ("complete", "checkout", "committed", "ok"):
        if result.get(field) is False:
            return True
    for field in ("unavailable", "missing", "conflicts", "unreachable"):
        if result.get(field):
            return True
    return False


