        parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)),
        object_pairs_hook=_object,
    )
    if type(core) is not dict or set(core) != {"components"} or type(core["components"]) is not dict:
        raise ValueError("invalid core object")
    components = core["components"]
    if any(type(result) is not dict for result in components.values()):
        raise ValueError("invalid component result")
